def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "issue_guarantee": And([
            self.outstanding_guarantees + 40 > 100,
            Not(self.authorized_cash_for_purchase < 40),
            self.database_online,
            self.audit_log_enabled
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
